try:
    def evaluate_policy(vars):
        import json, re, datetime
        vars['route'] = 'technical_hold'
        vars['speech'] = 'I could not complete that action.'
        vars['policy_error'] = ''
        def unpack(value, default):
            if isinstance(value, str):
                try:
                    value = json.loads(value)
                except Exception:
                    return default
            if isinstance(default, dict):
                return value if isinstance(value, dict) else default
            return value if isinstance(value, list) else default
        s = unpack(vars.get('call_state'), {})
        defaults_state = dict(phase='name', name_asks=0, wrong=0, declines=0, no_talk=0, human_asked=False, callback_invalid=0, products=[], loaded=False, notice='')
        for key, value in defaults_state.items():
            s.setdefault(key, value)
        vars['call_state'] = s
        speech_buffer = [str(vars.get('pending_speech', ''))]
        vars['pending_speech'] = ''
        now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00'))
        today = now.date()
        holidays = set(['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'])
        months = ['january','february','march','april','may','june','july','august','september','october','november','december']
        weekdays = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
        def business(day):
            return day.weekday() < 5 and day.isoformat() not in holidays
        def next_business(day):
            while not business(day):
                day += datetime.timedelta(days=1)
            return day
        def after_business(day, count):
            while count:
                day += datetime.timedelta(days=1)
                if business(day):
                    count -= 1
            return day
        def week_offer():
            day = today + datetime.timedelta(days=4-today.weekday())
            while not business(day):
                day -= datetime.timedelta(days=1)
            if day <= today:
                day = today + datetime.timedelta(days=11-today.weekday())
                while not business(day):
                    day -= datetime.timedelta(days=1)
            return day
        def amount(value):
            text = str(value).strip().replace(',', '')
            if not re.fullmatch(r'[0-9]+(?:\.[0-9]+)?', text):
                raise ValueError('Unresolved amount representation')
            number = float(text)
            if number != number or abs(number) == float('inf'):
                raise ValueError('Invalid amount')
            return number
        def money(value):
            number = float(value)
            if number != number or abs(number) == float('inf'):
                raise ValueError('Invalid amount')
            if number == int(number):
                return format(int(number), ',')
            text = str(number)
            if '.' in text and 'e' not in text.lower():
                whole, fraction = text.split('.')
                return format(int(whole), ',') + '.' + fraction
            return text
        def date_speech(value):
            day = datetime.date.fromisoformat(str(value))
            return str(day.day) + ' ' + months[day.month-1].title() + ' ' + str(day.year)
        def parse_date(raw, context=''):
            original = str(raw).strip()
            if not original:
                return 'missing', '', context
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', original):
                try:
                    return 'exact', datetime.date.fromisoformat(original).isoformat(), context
                except Exception:
                    return 'invalid', '', context
            text = re.sub(r'\s+', ' ', original.lower().replace('-', ' ').replace(',', ' ')).strip()
            for index, name in enumerate(months):
                aliases = [name[:3]] + (['sept'] if index == 8 else [])
                for alias in aliases:
                    text = re.sub(r'\b' + alias + r'\b\.?', name, text)
            for name in weekdays:
                text = re.sub(r'\b' + name[:3] + r'\b\.?', name, text)
            ordinals = ['first','second','third','fourth','fifth','sixth','seventh','eighth','ninth','tenth','eleventh','twelfth','thirteenth','fourteenth','fifteenth','sixteenth','seventeenth','eighteenth','nineteenth','twentieth','twenty first','twenty second','twenty third','twenty fourth','twenty fifth','twenty sixth','twenty seventh','twenty eighth','twenty ninth','thirtieth','thirty first']
            cardinals = ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen','twenty','twenty one','twenty two','twenty three','twenty four','twenty five','twenty six','twenty seven','twenty eight','twenty nine','thirty','thirty one']
            conversions = [(word, index+1) for index, word in enumerate(ordinals)] + [(word, index) for index, word in enumerate(cardinals)]
            for word, number in sorted(conversions, key=lambda item: len(item[0]), reverse=True):
                text = re.sub(r'\b' + word + r'\b', str(number), text)
            text = re.sub(r'(\d+)(?:st|nd|rd|th)\b', r'\1', text)
            relative = dict(today=0, tomorrow=1)
            if text in relative:
                return 'exact', (today + datetime.timedelta(days=relative[text])).isoformat(), context
            if text in ['this day','the next day','day after tomorrow','the day after tomorrow']:
                offset = 0 if text == 'this day' else (1 if text == 'the next day' else 2)
                return 'exact', (today + datetime.timedelta(days=offset)).isoformat(), context
            match = re.fullmatch(r'(?:in )?(\d+) days?(?: from today| from now)?', text)
            if match:
                return 'exact', (today + datetime.timedelta(days=int(match.group(1)))).isoformat(), context
            match = re.fullmatch(r'(\d+) weeks? from (?:today|now)', text)
            if match:
                return 'exact', (today + datetime.timedelta(days=7*int(match.group(1)))).isoformat(), context
            monday = today - datetime.timedelta(days=today.weekday())
            weekday_hits = [index for index, word in enumerate(weekdays) if re.search(r'\b' + word + r'\b', text)]
            if len(weekday_hits) > 1:
                return 'ambiguous', '', context
            weekday = weekday_hits[0] if weekday_hits else -1
            if weekday >= 0 and re.fullmatch(r'(?:on )?(?:this|next) ' + weekdays[weekday], text):
                offset = weekday + (7 if 'next' in text else 0)
                return 'exact', (monday + datetime.timedelta(days=offset)).isoformat(), context
            if re.search(r'\b(?:next week|following week|week after this)\b', text):
                context = 'week:' + (monday + datetime.timedelta(days=7)).isoformat()
            elif 'this week' in text:
                context = 'week:' + monday.isoformat()
            elif re.search(r'\b(?:next|following) month\b', text):
                next_month = (today.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
                context = 'month:' + next_month.strftime('%Y-%m')
            elif re.search(r'\b(?:this month|the month|current month)\b', text):
                context = 'month:' + today.strftime('%Y-%m')
            if weekday >= 0 and re.search(r'\b(?:this|next) ' + weekdays[weekday] + r'\b', text):
                context = 'week:' + (monday + datetime.timedelta(days=7 if re.search(r'\bnext ' + weekdays[weekday] + r'\b', text) else 0)).isoformat()
            match = re.fullmatch(r'(\d{1,2})[/.](\d{1,2})(?:[/.](\d{4}))?', text)
            if match:
                first, second = int(match.group(1)), int(match.group(2))
                year = int(match.group(3)) if match.group(3) else (int(context[6:10]) if context.startswith('month:') else today.year)
                candidates = []
                for day, month in [(first, second), (second, first)]:
                    try:
                        candidate = datetime.date(year, month, day)
                        if candidate not in candidates:
                            candidates.append(candidate)
                    except Exception:
                        pass
                if len(candidates) > 1 and context.startswith('month:'):
                    candidates = [day for day in candidates if day.strftime('%Y-%m') == context[6:]]
                if len(candidates) == 1:
                    return 'exact', candidates[0].isoformat(), 'month:' + candidates[0].strftime('%Y-%m')
                return 'ambiguous' if candidates else 'invalid', '', context
            month_hits = [index+1 for index, word in enumerate(months) if re.search(r'\b' + word + r'\b', text)]
            numbers = [int(value) for value in re.findall(r'\b\d+\b', text)]
            years = [value for value in numbers if value >= 1000]
            days = [value for value in numbers if 1 <= value <= 31]
            if len(month_hits) > 1 or len(years) > 1:
                return 'ambiguous', '', context
            if month_hits:
                year = years[0] if years else (int(context[6:10]) if context.startswith('month:') else today.year)
                context = 'month:' + str(year) + '-' + str(month_hits[0]).zfill(2)
            if len(days) == 1:
                candidates = []
                if context.startswith('week:'):
                    base = datetime.date.fromisoformat(context[5:])
                    candidates = [base + datetime.timedelta(days=index) for index in range(7)]
                    candidates = [day for day in candidates if day.day == days[0] and (not years or day.year == years[0])]
                elif context.startswith('month:'):
                    year, month = [int(value) for value in context[6:].split('-')]
                    try:
                        candidates = [datetime.date(years[0] if years else year, month, days[0])]
                    except Exception:
                        return 'invalid', '', context
                if weekday >= 0:
                    candidates = [day for day in candidates if day.weekday() == weekday]
                if len(candidates) == 1:
                    return 'exact', candidates[0].isoformat(), context
                return 'ambiguous', '', context
            if days or years:
                return 'ambiguous', '', context
            if weekday >= 0 and context.startswith('week:'):
                return 'exact', (datetime.date.fromisoformat(context[5:]) + datetime.timedelta(days=weekday)).isoformat(), context
            if month_hits or re.search(r'\b(?:week|month|salary|wages|payday|paycheck|payroll|pension|sometime|someday|later|eventually|soon|around|when|once|after)\b', text):
                return 'period', '', context
            return 'ambiguous', '', context
        def product_defaults(product):
            values = dict(status='open', attempts=0, floor_offered=False, floor_rejected=False, too_much=False, vague_asked=False, date_context='', rejected=[], writes=0, confirmed=False, noted=False)
            for key, value in values.items():
                product.setdefault(key, value)
        for product in s['products']:
            product_defaults(product)
        opening_text = 'I am a digital assistant calling from Freya Bank, and this call is recorded.'
        transcript = str(vars.get('system.conversation', ''))
        opening_seen = str(vars.get('id_opening_seen', 'none'))
        vars['id_opening_seen'] = 'none'
        if opening_seen == 'yes' or opening_text.lower() in transcript.lower():
            s['opening_spoken'] = True
            if s['phase'] == 'name':
                delivered = max(1, min(2, transcript.lower().count('am i speaking with')))
                s['name_asks'] = max(s['name_asks'], delivered)
        def authorized():
            return all(vars.get(key) == 'yes' for key in ['security_ready','dob_verified','phone_verified'])
        def ready():
            return authorized() and s.get('loaded') is True and 1 <= len(s['products']) <= 3
        def problem():
            s['recovering'] = True
            vars['route'] = 'technical_hold'
            vars['speech'] = 'I could not complete that action.'
        def emit(phase, text, target='identity_question'):
            s['phase'], s['question'] = phase, text
            vars['speech'] = speech_buffer[0] + text
            speech_buffer[0] = ''
            s['last_speech'] = vars['speech']
            vars['route'] = target
        def finish():
            products = s['products']
            if s.get('transfer_requested') and not s.get('transfer_success'):
                problem()
                return
            if s.get('transfer_success'):
                outcome = 'transferred'
                reason = dict(general='human', support='support', restructuring='restructuring')[s['transfer_success']]
            elif s.get('early_outcome'):
                outcome, reason = s['early_outcome'], s.get('early_reason', '')
            else:
                if not ready() or any(product['status'] in ['open','pending'] for product in products):
                    problem()
                    return
                for product in products:
                    if product['status'] != 'recorded' and not product['noted']:
                        vars['note_product'], vars['note_reason'] = product['product_id'], product['status']
                        vars['route'] = 'note_write'
                        return
                if any(product['status'] == 'recorded' for product in products):
                    outcome, reason = 'promise', ''
                elif all(product['status'] == 'paid' for product in products):
                    outcome, reason = 'paid', ''
                else:
                    outcome, reason = 'no_promise', next(product['status'] for product in products if product['status'] != 'paid')
            vars['close_outcome'], vars['close_reason'] = outcome, reason
            text = speech_buffer[0] + s.get('notice', '')
            speech_buffer[0] = ''
            if any(product['status'] == 'recorded' for product in products):
                text += 'Your payment promise has been recorded. You will receive a text message confirming this promise. '
            vars['speech'] = text + 'Thank you. Goodbye.'
            vars['route'] = 'farewell'
        def early(outcome, reason):
            s['early_outcome'], s['early_reason'] = outcome, reason
            finish()
        def ask_name():
            if s['name_asks'] >= 2:
                early('not_reached', 'unclear')
            else:
                s['name_asks'] += 1
                emit('name', 'Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '?')
        def ask_security():
            if vars.get('dob_verified') != 'yes':
                emit('dob', 'Please say the month of your birth as a word.' if s.get('month_word_required') else 'What is your date of birth?')
            else:
                emit('phone', 'What are the last four digits of the phone number on file?')
        def transfer(queue):
            s['transfer_requested'] = queue
            s.pop('ticket', None)
            vars['transfer_queue'], vars['route'] = queue, 'transfer_write'
        def human():
            if s['human_asked']:
                transfer('general')
                return
            s['human_asked'] = True
            s['resume_phase'], s['resume_speech'] = s['phase'], s.get('question', s.get('last_speech', ''))
            emit('human', 'May I try to help you first?', 'collection_question' if ready() else 'identity_question')
        def signature(value, day):
            return str(float(value)) + '|' + str(day)
        def base_terms(product, phase, focus):
            if product['status'] == 'pending':
                return product['amount'], product['date']
            if phase == 'offer' and s['products'][focus]['product_id'] == product['product_id']:
                return product.get('offer_amount', product['past_due']), product.get('offer_date', today.isoformat())
            return product['past_due'], today.isoformat()
        def reject(index, phase):
            product = s['products'][index]
            if product['status'] == 'recorded':
                return
            value, day = base_terms(product, phase, s.get('focus', index))
            if phase == 'offer':
                value, day = product.get('offer_amount', product['past_due']), product.get('offer_date', today.isoformat())
            key = signature(value, day)
            if key not in product['rejected']:
                product['rejected'].append(key)
            if value == product['floor'] and product['floor_offered']:
                product['floor_rejected'] = True
            product['status'], product['confirmed'], product['vague_asked'] = 'open', False, False
            product.pop('amount', None)
            product.pop('date', None)
        def readback():
            products = [product for product in s['products'] if product['status'] == 'pending']
            if not products:
                finish()
                return
            for product in products:
                product['confirmed'] = False
            s['readback_ids'] = [product['product_id'] for product in products]
            text = ' '.join('For your ' + product['label'] + ', ' + money(product['amount']) + ' on ' + date_speech(product['date']) + '.' for product in products)
            emit('confirm', text + ' Do you confirm?', 'collection_question')
        def offer(index):
            product = s['products'][index]
            s['focus'] = index
            if s.get('hardship'):
                if s.get('hardship_declined'):
                    product['status'] = 'hardship'
                    advance()
                else:
                    emit('support', 'Would you like me to connect you with the customer support team?', 'collection_question')
                return
            product['status'], product['confirmed'] = 'open', False
            while product['attempts'] < product['budget']:
                product['attempts'] += 1
                value = product['floor'] if product['attempts'] == 2 or product['too_much'] else product['past_due']
                day = product['deadline'] if product['attempts'] == 2 else week_offer().isoformat()
                if product['attempts'] == 1 and value == product['floor'] and product['floor_rejected']:
                    continue
                if signature(value, day) in product['rejected']:
                    continue
                product['offer_amount'], product['offer_date'] = value, day
                text = ''
                if value < product['past_due']:
                    product['floor_offered'] = True
                    text = 'The rest stays overdue. '
                emit('offer', text + 'Can you pay ' + money(value) + ' for your ' + product['label'] + ' on ' + date_speech(day) + '?', 'collection_question')
                return
            product['status'] = 'refused'
            advance()
        def advance():
            for index, product in enumerate(s['products']):
                if product['status'] == 'open':
                    offer(index)
                    return
            readback()
        def resolve(reference, kind, phase, focus, readback_ids):
            products = s['products']
            text = re.sub(r'\s+', ' ', re.sub(r'[^a-z0-9 ]', ' ', str(reference).lower())).strip()
            if text in ['all','both','everything','all of them','all products','all three','the lot']:
                return list(range(len(products)))
            if not text:
                if len(products) == 1:
                    return [0]
                if phase == 'confirm':
                    indices = [index for index, product in enumerate(products) if product['product_id'] in readback_ids]
                    return indices if len(indices) == 1 else []
                if phase == 'all' and kind == 'promise':
                    return list(range(len(products)))
                return [focus] if phase == 'offer' else []
            simple = re.sub(r'\s+', ' ', re.sub(r'\b(?:my|the|our|that|this)\b', '', text)).strip()
            hits = []
            for index, product in enumerate(products):
                hit = text == str(product['product_id']).lower() or text == product.get('label', '').lower()
                if product.get('type') == 'credit_card' and re.search(r'\b(?:card|credit)\b', text):
                    suffixes = re.findall(r'\b\d{4}\b', text)
                    hit = not suffixes or product.get('card_last4') in suffixes
                if product.get('type') == 'personal_loan' and re.search(r'\bpersonal\b', text):
                    hit = True
                if product.get('type') == 'car_loan' and re.search(r'\b(?:car|auto|vehicle)\b', text):
                    hit = True
                if simple == 'loan' and product.get('type') in ['personal_loan','car_loan']:
                    hit = True
                if text == product.get('card_last4', ''):
                    hit = True
                if hit:
                    hits.append(index)
            return hits if len(hits) == 1 else []
        def prepare_write():
            if not ready() or s.get('transfer_requested'):
                problem()
                return
            for product in s['products']:
                if product['status'] == 'pending' and product['confirmed']:
                    day = datetime.date.fromisoformat(product['date'])
                    valid = product['floor'] <= product['amount'] <= product['past_due'] and today <= day <= datetime.date.fromisoformat(product['deadline']) and business(day)
                    if not valid or product['writes'] >= 2:
                        problem()
                        return
                    product['writes'] += 1
                    vars['write_product'], vars['write_amount'], vars['write_date'] = product['product_id'], product['amount'], product['date']
                    vars['route'] = 'promise_write'
                    return
            finish()
        def scope_question(ticket):
            ticket['waiting'] = 'scope'
            emit('scope', 'Which product do you mean: ' + ', '.join(product['label'] for product in s['products']) + '?', 'collection_question')
        def process_ticket():
            ticket, products = s['ticket'], s['products']
            while ticket['position'] < len(ticket['slots']):
                slot = ticket['slots'][ticket['position']]
                indices = [index for index, product in enumerate(products) if product['product_id'] in slot.get('ids', [])]
                if not indices:
                    indices = resolve(slot.get('ref', ''), slot['kind'], ticket['origin'], ticket['focus'], ticket['readback_ids'])
                    if not indices:
                        scope_question(ticket)
                        return
                    slot['ids'] = [products[index]['product_id'] for index in indices]
                later_indices = []
                for later in ticket['slots'][ticket['position']+1:]:
                    later_indices.extend(resolve(later.get('ref', ''), later['kind'], ticket['origin'], ticket['focus'], ticket['readback_ids']))
                if any(index in later_indices for index in indices):
                    ticket['waiting'] = 'conflict'
                    emit('scope', 'Please clarify the corrected terms for the product mentioned more than once.', 'collection_question')
                    return
                active = [index for index in indices if products[index]['status'] != 'recorded']
                if len(active) != len(indices):
                    speech_buffer[0] += 'You can change a recorded promise in the mobile app. '
                if not active:
                    ticket['position'] += 1
                    continue
                if slot['kind'] in ['paid','dispute']:
                    for index in active:
                        products[index]['status'], products[index]['confirmed'] = slot['kind'], False
                    if slot['kind'] == 'paid':
                        speech_buffer[0] += 'Payments can take one business day to appear. '
                    ticket['position'] += 1
                    continue
                if slot['kind'] == 'refused':
                    for index in active:
                        reject(index, ticket['origin'])
                    ticket['position'] += 1
                    continue
                if slot['kind'] == 'too_much' and ticket['origin'] == 'all':
                    for index in active:
                        products[index]['too_much'] = True
                    ticket['position'] += 1
                    continue
                if slot['kind'] == 'promise' and not slot.get('amount') and not slot.get('date') and not slot.get('accepted') and not slot.get('deadline') and not slot.get('full_amount'):
                    ticket['waiting'] = 'terms'
                    emit(ticket['origin'], 'Please clarify the payment date or whether you accept the stated offer.', 'collection_question')
                    return
                values, invalid_amount = [], False
                for index in active:
                    product = products[index]
                    base_amount, base_date = base_terms(product, ticket['origin'], ticket['focus'])
                    try:
                        value = product['floor'] if slot['kind'] == 'too_much' else (product['past_due'] if slot.get('full_amount') else (amount(slot['amount']) if slot.get('amount') else base_amount))
                    except Exception:
                        invalid_amount = True
                        break
                    mode, day, context = parse_date(slot.get('date') or base_date, product['date_context'])
                    form = slot.get('date_form', 'none')
                    if form == 'period' and mode == 'ambiguous':
                        mode = 'period'
                    elif (form == 'period' and mode == 'exact') or (form == 'exact' and mode == 'period') or form == 'unknown':
                        mode = 'ambiguous'
                    product['date_context'] = context
                    if slot.get('deadline'):
                        mode, day = 'deadline', product['deadline']
                    values.append((index, value, mode, day))
                if invalid_amount:
                    ticket['waiting'] = 'amount'
                    text = ' and '.join(money(products[index]['past_due']) + ' for your ' + products[index]['label'] for index in active)
                    emit('amount', 'I could not understand that amount. Can you pay ' + text + '?', 'collection_question')
                    return
                unresolved = [value for value in values if value[2] not in ['exact','deadline']]
                if unresolved:
                    period = all(value[2] == 'period' for value in unresolved)
                    if period and any(products[index]['vague_asked'] for index in active):
                        slot['deadline'] = True
                        continue
                    ticket['waiting'], ticket['date_reason'] = 'date', 'period' if period else 'representation'
                    if period:
                        for index in active:
                            products[index]['vague_asked'] = True
                    labels = ' and '.join(products[index]['label'] for index in active)
                    text = 'What exact day do you mean for your ' + labels + '?' if period else 'Please give the exact payment day and month for your ' + labels + '.'
                    emit('date', text, 'collection_question')
                    return
                if any(datetime.date.fromisoformat(day) < today for index, value, mode, day in values):
                    ticket['waiting'], ticket['date_reason'] = 'date', 'past'
                    emit('date', 'That date is in the past. Please give today or a later business day, no later than ' + date_speech(min(products[index]['deadline'] for index in active)) + '.', 'collection_question')
                    return
                for index, value, mode, raw_day in values:
                    product = products[index]
                    if slot['kind'] == 'too_much':
                        product['too_much'] = True
                        if product['floor_offered']:
                            reject(index, ticket['origin'])
                            continue
                        product['floor_offered'] = True
                    if value < product['floor']:
                        if product['floor_offered']:
                            reject(index, ticket['origin'])
                            continue
                        speech_buffer[0] += 'I cannot record that amount. I can offer ' + money(product['floor']) + ' for your ' + product['label'] + '; the rest stays overdue. '
                        value = product['floor']
                        product['floor_offered'], product['too_much'] = True, True
                    elif value > product['past_due']:
                        speech_buffer[0] += 'The past-due amount for your ' + product['label'] + ' is ' + money(product['past_due']) + '. I can offer that amount. '
                        value = product['past_due']
                    day, deadline = datetime.date.fromisoformat(raw_day), datetime.date.fromisoformat(product['deadline'])
                    if mode == 'deadline':
                        speech_buffer[0] += 'I can offer ' + date_speech(product['deadline']) + ', the latest date I can record for your ' + product['label'] + '. '
                    elif day > deadline:
                        day = deadline
