                        scope_question(ticket)
                    return
                if not fresh:
                    emit(s['phase'], s.get('question', 'Please clarify your reply.'), 'collection_question')
                    return
                if waiting == 'conflict':
                    replacements, resolved_indices = [], []
                    for slot in fresh:
                        indices = resolve(slot['ref'], slot['kind'], ticket['origin'], ticket['focus'], ticket['readback_ids'])
                        if not indices or slot['kind'] == 'none' or (slot['kind'] == 'promise' and not slot['amount'] and not slot['date']):
                            emit('scope', 'Please clarify the corrected terms for the product mentioned more than once.', 'collection_question')
                            return
                        resolved_indices.extend(indices)
                        replacements.append(slot)
                    retained = []
                    for slot in ticket['slots'][ticket['position']:]:
                        indices = resolve(slot.get('ref', ''), slot['kind'], ticket['origin'], ticket['focus'], ticket['readback_ids'])
                        remaining = [index for index in indices if index not in resolved_indices]
                        if remaining:
                            slot['ids'] = [products[index]['product_id'] for index in remaining]
                            retained.append(slot)
                    ticket['slots'] = ticket['slots'][:ticket['position']] + replacements + retained
                    process_ticket()
                    return
                first = fresh[0]
                target_indices = resolve(first['ref'], first['kind'], ticket['origin'], ticket['focus'], ticket['readback_ids']) if first['ref'] else []
                old_indices = [index for index, product in enumerate(products) if product['product_id'] in current.get('ids', [])]
                if first['ref'] and old_indices and target_indices and not set(target_indices).issubset(set(old_indices)):
                    ticket['slots'].extend(fresh)
                    emit(s['phase'], s.get('question', 'Please clarify your reply.'), 'collection_question')
                    return
                if first['ref'] and old_indices and not target_indices:
                    ticket['unresolved_reference'] = first['ref']
                    emit(s['phase'], 'Please identify the product you mean before I change those terms.', 'collection_question')
                    return
                if target_indices and old_indices and set(target_indices) != set(old_indices):
                    remaining = dict(current)
                    remaining['ids'] = [products[index]['product_id'] for index in old_indices if index not in target_indices]
                    ticket['slots'].insert(ticket['position']+1, remaining)
                    current['ids'] = [products[index]['product_id'] for index in target_indices]
                if first['kind'] in ['paid','dispute','refused']:
                    current['kind'], current['amount'], current['date'], current['date_form'] = first['kind'], '', '', 'none'
                    current.pop('deadline', None)
                elif first['kind'] in ['promise','too_much']:
                    current['kind'] = first['kind']
                for key in ['ref','amount','date']:
                    if first.get(key):
                        current[key] = first[key]
                if first.get('date'):
                    current['date_form'] = first['date_form']
                    current.pop('deadline', None)
                if first.get('ref') and not old_indices:
                    current.pop('ids', None)
                ticket['slots'].extend(fresh[1:])
                process_ticket()
                return
            if event == 'yes' and not fresh:
                if s['phase'] == 'confirm':
                    for product in products:
                        if product['status'] == 'pending' and product['product_id'] in s.get('readback_ids', []):
                            product['confirmed'] = True
                    prepare_write()
                    return
                if s['phase'] in ['all','offer']:
                    fresh = [dict(kind='promise', ref='all' if s['phase'] == 'all' else '', amount='', date='', date_form='none', accepted=True)]
                else:
                    emit(s['phase'], 'Please give the exact payment day you mean.', 'collection_question')
                    return
            if event in ['no','nonanswer'] and not fresh:
                if s.get('hardship'):
                    emit('support', 'Would you like me to connect you with the customer support team?', 'collection_question')
                    return
                if s['phase'] == 'confirm':
                    for index, product in enumerate(products):
                        if product['status'] == 'pending' and product['product_id'] in s.get('readback_ids', []):
                            reject(index, 'confirm')
                    advance()
                elif s['phase'] == 'all':
                    offer(0)
                else:
                    index = s.get('focus', 0)
                    reject(index, s['phase'])
                    offer(index)
                return
            if not fresh:
                emit(s['phase'], 'Please clarify whether you accept the stated offer or which payment date you mean.', 'collection_question')
                return
            for slot in fresh:
                if slot['kind'] == 'none':
                    if event in ['paid','dispute']:
                        slot['kind'] = event
                    elif event in ['proposal','correction'] and (slot['amount'] or slot['date']):
                        slot['kind'] = 'promise'
                    else:
                        emit(s['phase'], 'Please clarify the payment date or whether you accept the stated offer.', 'collection_question')
                        return
                if event == 'yes' and slot['kind'] == 'promise' and s['phase'] in ['all','offer']:
                    slot['accepted'] = True
            s['ticket'] = dict(slots=fresh, position=0, origin=s['phase'], focus=s.get('focus', 0), readback_ids=list(s.get('readback_ids', [])), waiting='')
            process_ticket()
        run()
        vars['pending_speech'] = speech_buffer[0]
        vars['call_state'] = s
    evaluate_policy(vars)
except Exception as error:
    vars['policy_error'] = str(error)
    vars['route'] = 'technical_hold'
    vars['speech'] = 'I could not complete that action.'
    saved_state = vars.get('call_state', {})
    if isinstance(saved_state, dict):
        saved_state['recovering'] = True
        vars['call_state'] = saved_state

